// Parity checks of the Anima prompt layer (src/anima/text/) against the Python source of truth.
//
// The fixture `anima-text/parity.json` is generated by the exporter. It contains
//  - the reference id sequences (Qwen2 / T5) of every case and the T5-normalised strings. **The
//    source of truth is transformers' AutoTokenizer** (called the same way as the pipeline's source
//    of truth)
//  - the **subset** of the vocabulary and merges needed to reproduce them (the licensed material is
//    not committed whole)
//  - the **whole** normalisation tables, character-class tables and NFC segment tables (folding
//    itself is under test, so they are not trimmed)
//  - NFC `[input, reference output]` pairs (measured values a plain `normalize("NFC")` cannot
//    reproduce)
//
// It mainly pins one behaviour: "the same string gives the same id sequence as Python". How the
// tables are held is not pinned (changing the implementation stays green if the meaning does not
// change). **The exception is a few direct calls**, which pin rules that do not show in the id
// sequence (measured by fault injection) on the splitting and normalisation themselves.
//
// NOTE: The fixture lives in `packages/models/tests/fixtures/anima-text/` (its consumer is this
// test, so the models side is authoritative — moved on 2026-08-16). The exporter's generation and
// references point at the same path.

import { readTextFile } from "@karume/test-support/fs";
import { test } from "vite-plus/test";
import { assert, assertEquals, assertThrows } from "@std/assert";
import {
  normalizeNfc,
  type Qwen2Assets,
  qwen2PreTokenize,
  Qwen2Tokenizer,
} from "../src/text/qwen2-tokenizer.ts";
import { normalizeSpm, parseSpmTables } from "../src/anima/text/spm-normalizer.ts";
import { type T5Assets, T5Tokenizer } from "../src/anima/text/t5-tokenizer.ts";
import {
  AnimaTokenizers,
  assertPromptTokenLengths,
  createTokenizers,
  PROMPT_MIN_TOKENS,
} from "../src/anima/text/tokenizer.ts";
import { ModelInputError } from "../src/errors.ts";
import { splitAddedTokens } from "../src/text/added-tokens.ts";
import { toCodePoints } from "../src/text/code-points.ts";
import { parseCodeRanges } from "../src/text/code-ranges.ts";
import { t5PreTokenize, type T5VocabEntry } from "../src/text/t5-tokenizer.ts";

type FixtureCase = {
  readonly id: string;
  readonly why: string;
  readonly text: string;
  readonly qwenIds: number[];
  readonly t5Ids: number[];
  readonly t5Normalized: string;
};

type Fixture = {
  readonly maxLength: number;
  readonly qwen: {
    readonly addedTokens: [string, number][];
    readonly classes: { letter: unknown; number: unknown; space: unknown };
    readonly caseFold: [number, number][];
    readonly nfcSegments: unknown;
    readonly nfcCases: [string, string][];
    readonly vocab: Record<string, number>;
    readonly merges: [string, string, number][];
  };
  readonly t5: {
    readonly addedTokens: [string, number][];
    readonly unkId: number;
    readonly eosId: number;
    readonly minScore: number;
    readonly maxTokenLength: number;
    readonly space: unknown;
    readonly normalizer: unknown;
    readonly vocab: [string, number, number][];
  };
  readonly cases: FixtureCase[];
};

const FIXTURE_PATH = new URL("./fixtures/anima-text/parity.json", import.meta.url);
const fixture = JSON.parse(await readTextFile(FIXTURE_PATH)) as Fixture;

const qwenAssets: Qwen2Assets = {
  vocab: new Map(Object.entries(fixture.qwen.vocab)),
  merges: new Map(fixture.qwen.merges.map(([left, right, rank]) => [`${left} ${right}`, rank])),
  addedTokens: new Map(fixture.qwen.addedTokens),
  caseFold: new Map(fixture.qwen.caseFold),
  nfcSegments: parseCodeRanges(fixture.qwen.nfcSegments, "nfcSegments"),
  classes: {
    letter: parseCodeRanges(fixture.qwen.classes.letter, "letter"),
    number: parseCodeRanges(fixture.qwen.classes.number, "number"),
    space: parseCodeRanges(fixture.qwen.classes.space, "space"),
  },
  maxLength: fixture.maxLength,
};

const t5Assets: T5Assets = {
  vocab: new Map<string, T5VocabEntry>(
    fixture.t5.vocab.map(([token, id, score]) => [token, { id, score }]),
  ),
  // MUST: do not derive from the subset — the unknown-node score and the search width are
  // determined by the **whole** vocabulary.
  minScore: fixture.t5.minScore,
  maxTokenLength: fixture.t5.maxTokenLength,
  unkId: fixture.t5.unkId,
  eosId: fixture.t5.eosId,
  addedTokens: new Map(fixture.t5.addedTokens),
  space: parseCodeRanges(fixture.t5.space, "space"),
  normalizer: parseSpmTables(fixture.t5.normalizer, "normalizer"),
  maxLength: fixture.maxLength,
};

const qwen = new Qwen2Tokenizer(qwenAssets);
const t5 = new T5Tokenizer(t5Assets);

const caseById = (id: string): FixtureCase => {
  const found = fixture.cases.find((entry) => entry.id === id);
  if (found === undefined) throw new Error(`the fixture has no case ${id}`);
  return found;
};

// ---- The fixture itself ------------------------------------------------------

test("the fixture is not empty (a mix-up has not let every case pass through)", () => {
  // Placed first. If a misread / failed generation left cases empty, the loops below would run zero
  // times and the state "green but checking nothing" would hold silently.
  assert(fixture.cases.length >= 28, `case count ${fixture.cases.length} is too small`);
  assertEquals(fixture.maxLength, 512);
  assert(Object.keys(fixture.qwen.vocab).length > 0, "the Qwen2 vocabulary subset is empty");
  assert(fixture.t5.vocab.length > 0, "the T5 vocabulary subset is empty");
});

for (const testCase of fixture.cases) {
  test(`parity [${testCase.id}] ${testCase.why}`, () => {
    assertEquals(qwen.encode(testCase.text), testCase.qwenIds, "Qwen2 id sequence");
    assertEquals(t5.encode(testCase.text), testCase.t5Ids, "T5 id sequence");
  });
}

test("the T5 normalisation result itself matches the source of truth (isolated before the id sequence)", () => {
  for (const testCase of fixture.cases) {
    assertEquals(
      normalizeSpm(t5Assets.normalizer, testCase.text),
      testCase.t5Normalized,
      `normalised string of [${testCase.id}]`,
    );
  }
});

// ---- NFC (the area where the source of truth and JS engines disagree) -------------------------

test("NFC: reproduces with the segment table the inputs on which the source of truth differs (values a plain normalize cannot produce)", () => {
  // Each pair in the fixture is a measured value of `tokenizers.normalizers.NFC`. ① one per segment
  // cp (contexts where plain NFC always misses) ② random — ② is the net for ICU drifting from
  // Python outside the segments.
  assert(fixture.qwen.nfcCases.length >= 200, `only ${fixture.qwen.nfcCases.length} NFC cases`);
  for (const [text, want] of fixture.qwen.nfcCases) {
    assertEquals(
      normalizeNfc(text, qwenAssets.nfcSegments),
      want,
      `NFC [${Array.from(text)
        .map((ch) => (ch.codePointAt(0) as number).toString(16))
        .join(" ")}]`,
    );
  }
});

test("NFC: dropping one range from the segment table falls back to plain normalize (= a different id sequence)", () => {
  // Measured (the result of feeding the same string to `tokenizers`' NFC): the source of truth
  // treats U+089A as combining class 0 and so **does not reorder**. ICU (V8) reorders because ccc
  // 220 < 230.
  const text = "\u0818\u089A";
  assertEquals(
    normalizeNfc(text, qwenAssets.nfcSegments),
    text,
    "with the segment table = the source of truth",
  );
  assertEquals(text.normalize("NFC"), "࢚࠘", "plain NFC reorders");
  const dropped = qwenAssets.nfcSegments.filter(
    ([start, end]) => !(start <= 0x089a && 0x089a <= end),
  );
  assertEquals(
    normalizeNfc(text, dropped),
    "࢚࠘",
    "dropped from the table, it differs from the source of truth",
  );
});

// ---- Boundaries (what the fixture's cases actually exercise) --------------------------

test("input beyond 512 is truncated and T5 always ends with `</s>`", () => {
  const long = caseById("long");
  assertEquals(long.qwenIds.length, fixture.maxLength);
  const ids = t5.encode(long.text);
  // The truncation takes effect **before** `</s>` (appending after would give 513).
  assertEquals(ids.length, fixture.maxLength);
  assertEquals(ids.at(-1), fixture.t5.eosId);
});

test("an unpaired surrogate is not accepted (no silently passing input the source of truth does not have)", () => {
  assertThrows(() => toCodePoints("a\ud800b"), Error, "surrogate");
  assertThrows(() => qwen.encode("a\ud800b"), Error, "surrogate");
  assertThrows(() => t5.encode("a\ud800b"), Error, "surrogate");
});

test("added tokens are leftmost-longest (a string that matches only partway is not cut out)", () => {
  const added = ["<|endoftext|>", "<|im_start|>"];
  assertEquals(splitAddedTokens("a<|endoftext|>b", added), [
    { text: "a", added: false },
    { text: "<|endoftext|>", added: true },
    { text: "b", added: false },
  ]);
  // A partial match (`<|endoftext|x`) cuts out nothing.
  assertEquals(splitAddedTokens("<|endoftext|x", added), [{ text: "<|endoftext|x", added: false }]);
  // At the same position the longer one wins (putting the shorter candidate first does not change
  // the result).
  assertEquals(splitAddedTokens("<|a|>", ["<|a|>", "<|a"]), [{ text: "<|a|>", added: true }]);
  // An empty added token matches at every position and the scan does not advance (the seed of an
  // infinite loop).
  assertThrows(() => splitAddedTokens("abc", ["", "<|a"]), Error, "empty string");
});

test("range tables: a table that is not ascending and non-overlapping is not accepted (no silently classifying differently)", () => {
  // `inCodeRanges` is a binary search, so an out-of-order table raises no exception and only
  // changes the verdicts.
  assertEquals(
    parseCodeRanges(
      [
        [1, 2],
        [4, 9],
      ],
      "table",
    ),
    [
      [1, 2],
      [4, 9],
    ],
  );
  assertThrows(() => parseCodeRanges([[5, 1]], "table"), Error, "has a start greater than its end");
  assertThrows(
    () =>
      parseCodeRanges(
        [
          [4, 6],
          [1, 2],
        ],
        "table",
      ),
    Error,
    "is not in ascending order",
  );
  assertThrows(
    () =>
      parseCodeRanges(
        [
          [1, 5],
          [5, 9],
        ],
        "table",
      ),
    Error,
    "overlaps",
  );
  assertThrows(
    () => parseCodeRanges([[1, 2], [4]], "table"),
    Error,
    "is not a [start, end] number pair",
  );
});

test("normalisation: a combining-character cluster emits only the shortest matching prefix and drops the rest", () => {
  const normalize = (text: string): string => normalizeSpm(t5Assets.normalizer, text);
  // A + U+0301 has a rule, so it gives U+00C1. Adding another U+0301 still gives U+00C1 (the third
  // character is dropped). **Do not write precomposed characters** — inputs are always spelt in
  // decomposed form.
  assertEquals(normalize("A\u0301"), "\u00C1");
  assertEquals(normalize("A\u0301\u0301"), "\u00C1");
  // The 2cp prefix U+00C2 wins over the 3cp rule U+1EA4 (an implementation as "longest match"
  // misses here).
  assertEquals(normalize("A\u0302\u0301"), "\u00C2");
});

test("normalisation: a cluster of 6 bytes or more does not take the whole-replacement path", () => {
  // A(1) + U+0302(2) + U+0301(2) + U+0301(2) = 7 bytes → one character at a time (nothing is
  // composed).
  assertEquals(normalizeSpm(t5Assets.normalizer, "A\u0302\u0301\u0301"), "A\u0302\u0301\u0301");
});

test("normalisation: a cluster of exactly 6 bytes does not take the whole-replacement path either (the boundary itself)", () => {
  // U+00A0(2) + U+0300(2) + U+0300(2) = **exactly 6 bytes**. Rewriting `<` as `<=` makes the 1cp
  // rule "U+00A0 → space" fire as a whole replacement, and the two combining characters vanish
  // silently. The two existing direct calls have only 5 and 7 bytes and let this one-character
  // rewrite through (so do the 28 parity cases — measured by fault injection).
  assertEquals(normalizeSpm(t5Assets.normalizer, "\u00A0\u0300\u0300"), " \u0300\u0300");
});

test("normalisation: a cluster breaks right after a control character (combining characters are not pulled in)", () => {
  const normalize = (text: string): string => normalizeSpm(t5Assets.normalizer, text);
  // U+0009 maps to a space. The U+0301 right after it is a separate cluster, so it stays as is.
  assertEquals(normalize("\t\u0301"), " \u0301");
  // CR LF is one cluster (GB3), so it folds into a single space.
  assertEquals(normalize("\r\n"), " ");
  assertEquals(normalize("\n\n"), "  ");
});

// ---- Rules the fixture's cases **do not reach** (pinned directly with synthetic inputs) --------
//
// The four below are rules that fault injection showed "cannot be detected by the fixture's id
// sequences alone" (① the `(?i:)` equivalence ② `\p{N}` splitting one character at a time
// ③ Viterbi tie handling ④ Metaspace's MergedWithNext). For ① and ② the byte-level BPE re-merges
// after the split changes and gives the same id sequence, and ③ and ④ are not hit by real prompts.
// All of them are rules matched to the source of truth, so a rewrite would pass quietly unless
// synthetic inputs call them directly.

test("pre-token: the `(?i:)` equivalence is looked up in the baked table (not ASCII-equivalent)", () => {
  // Measured (the result of feeding the same string to `tokenizers`' Split): the source of truth
  // splits `it'ſs` into `it` / `'ſ` / `s` — Rust's `(?i:)` uses simple case folding, so U+017F ≡ s.
  // **The id sequence does not catch it** (the byte-level BPE re-merges into the same sequence), so
  // the split itself is checked. ASCII case flipping or `toLowerCase()` gives the single chunk
  // `'ſs` here and fails.
  const split = (text: string): string[] =>
    qwen2PreTokenize(toCodePoints(text), qwenAssets.classes, qwenAssets.caseFold);
  assertEquals(split("it'ſs"), ["it", "'ſ", "s"]);
  assertEquals(split("it'S"), ["it", "'S"]);
  assertEquals(split("it's"), ["it", "'s"]);
  // The table itself contains U+017F → s (dropping it would make the expected value above
  // unattainable).
  assertEquals(qwenAssets.caseFold.get(0x017f), "s".codePointAt(0));
});

test("pre-token: `\\p{N}` splits one character at a time (no `+`)", () => {
  // **The id sequence does not catch it** (Qwen2's merges have no digit merges, so fault injection
  // showed that even a greedy version gives the same sequence on the real assets). Without checking
  // the split itself a rewrite would pass quietly.
  const split = (text: string): string[] =>
    qwen2PreTokenize(toCodePoints(text), qwenAssets.classes, qwenAssets.caseFold);
  assertEquals(split("2024"), ["2", "0", "2", "4"]);
  assertEquals(split("1.5x"), ["1", ".", "5", "x"]);
});

test("Viterbi: on a tie the longer chunk wins (the comparison is a strict `>`)", () => {
  // a(-1) + b(-1) and ab(-2) tie exactly. Measuring the source of truth (tokenizers' Unigram) with
  // the same vocabulary gives a single `ab` (nodes ending at the same position are pushed in
  // ascending order of start position, and on a tie the one pushed first = the longer one remains).
  // With `>=` it silently becomes the two tokens a, b.
  const tie = new T5Tokenizer({
    vocab: new Map<string, T5VocabEntry>([
      ["▁", { id: 3, score: -1 }],
      ["a", { id: 4, score: -1 }],
      ["b", { id: 5, score: -1 }],
      ["ab", { id: 6, score: -2 }],
    ]),
    minScore: -2,
    maxTokenLength: 2,
    unkId: 2,
    eosId: 1,
    addedTokens: new Map(),
    space: [[0x20, 0x20]],
    normalizer: parseSpmTables(
      { single: [], multi: [], extend: [], breakAfter: [], prepend: [] },
      "empty",
    ),
    maxLength: 512,
  });
  assertEquals(tie.encode("ab"), [3, 6, 1], "▁ + ab + </s>");
});

// ---- Very long input (nothing after the truncation is encoded) ------------------------------

/** A T5 with only the vocabulary `▁` / `a`. A run of `a` gives one id per character. */
const tinyT5 = (vocab: Map<string, T5VocabEntry>): T5Tokenizer =>
  new T5Tokenizer({
    vocab,
    minScore: -1,
    maxTokenLength: 2,
    unkId: 2,
    eosId: 1,
    addedTokens: new Map(),
    space: [[0x20, 0x20]],
    normalizer: parseSpmTables(
      { single: [], multi: [], extend: [], breakAfter: [], prepend: [] },
      "empty",
    ),
    maxLength: 512,
  });

const tinyVocabEntries = (): [string, T5VocabEntry][] => [
  ["▁", { id: 3, score: -1 }],
  ["a", { id: 4, score: -1 }],
];

/**
 * A vocabulary that throws as soon as a chunk containing `z` is looked up (the observation point of
 * encoding past the truncation).
 */
class TrapVocab extends Map<string, T5VocabEntry> {
  override get(key: string): T5VocabEntry | undefined {
    if (key.includes("z")) throw new Error("encoded a chunk past the truncation");
    return super.get(key);
  }
}

test("T5: a huge single chunk without spaces does not hit the argument limit and is truncated to 512", () => {
  // Once one chunk exceeds about 100,000 ids, `push(...ids)` throws a RangeError at V8's argument
  // limit.
  const ids = tinyT5(new Map(tinyVocabEntries())).encode("a".repeat(300_000));
  assertEquals(ids.length, 512);
  assertEquals(ids, [3, ...Array.from({ length: 510 }, () => 4), 1], "▁ + a × 510 + </s>");
});

test("T5: following chunks discarded by the truncation are not encoded", () => {
  const trap = tinyT5(new TrapVocab(tinyVocabEntries()));
  // Premise: encoding the sentinel chunk throws (the vocabulary trap works).
  assertThrows(() => trap.encode("z"), Error, "past the truncation");
  // One `▁a` chunk = 2 ids, so 600 chunks exceed the budget of 511 and never reach the trailing
  // `▁z`.
  const ids = trap.encode("a ".repeat(600) + "z");
  assertEquals(ids.length, 512);
  assertEquals(ids.at(-1), 1);
});

test("Qwen2: following pre-tokens discarded by the truncation are not encoded", () => {
  // The sentinel `ק` is not in the vocabulary subset, so encoding it would throw with "token not in
  // the vocabulary".
  const sentinel = " ק";
  assertThrows(() => qwen.encode(sentinel), Error, "is not in the Qwen2 vocabulary");
  const long = caseById("long");
  assertEquals(qwen.encode(long.text + sentinel), long.qwenIds);
});

test("Metaspace: a separating ▁ attaches to the start of the next chunk (MergedWithNext)", () => {
  const space: readonly (readonly [number, number])[] = [[0x20, 0x20]];
  // A ▁ is always added at the start (prepend_scheme=always), and a ▁ in the input **splits at that
  // position and goes to the next chunk**.
  assertEquals(t5PreTokenize("under▁score", space), ["▁under", "▁score"]);
  assertEquals(t5PreTokenize("abc", space), ["▁abc"]);
  assertEquals(t5PreTokenize("a b", space), ["▁a", "▁b"]);
  // Consecutive ▁ do not produce empty chunks.
  assertEquals(t5PreTokenize("a▁▁b", space), ["▁a", "▁", "▁b"]);
});

// ---- Accepted set (Dim(min=2)) --------------------------------------------------

test("accepted set: an empty or whitespace-only prompt fails loudly", () => {
  // Even for the empty string T5 gives length 1 with only `</s>`, outside Dim("Ttgt", min=2).
  assertEquals(t5.encode(""), [fixture.t5.eosId]);
  assertEquals(caseById("only_space").t5Ids.length, 1);
  assertThrows(
    () => assertPromptTokenLengths("negative prompt", 0, 1, fixture.maxLength),
    ModelInputError,
    "negative prompt",
  );
});

test("accepted set: a one-character prompt falls outside on the Qwen2 side with one token", () => {
  const single = caseById("single_char");
  assertEquals(single.qwenIds.length, 1);
  // The T5 side can reach 2 or more with `▁a` + `</s>` and the like, so it is caught only **by
  // checking both sides**.
  assert(single.t5Ids.length >= PROMPT_MIN_TOKENS);
  assertThrows(
    () =>
      assertPromptTokenLengths(
        "prompt",
        single.qwenIds.length,
        single.t5Ids.length,
        fixture.maxLength,
      ),
    ModelInputError,
    "Qwen2",
  );
});

test("accepted set: an ordinary tag list is accepted and exceeding the upper bound is rejected", () => {
  const tags = caseById("tags");
  assertPromptTokenLengths("prompt", tags.qwenIds.length, tags.t5Ids.length, fixture.maxLength);
  // The upper side is an internal invariant reached only when the truncation breaks, so it is not
  // raised with the input-caused type.
  assertThrows(
    () => assertPromptTokenLengths("prompt", fixture.maxLength + 1, 4, fixture.maxLength),
    Error,
    "upper bound",
  );
});

// ---- The entry of the pair (AnimaTokenizers / createTokenizers) ------------------------

test("AnimaTokenizers: rejects assets where only one side is stale (a maxLength mismatch)", () => {
  // With different truncation lengths only the id sequence lengths of long prompts disagree, which
  // would not surface until the conditioner's 512-padding check.
  assertThrows(
    () => new AnimaTokenizers(qwenAssets, { ...t5Assets, maxLength: 256 }),
    Error,
    "maxLength of the tokenizer assets does not match",
  );
});

test("AnimaTokenizers: the message shows whether the positive or the negative prompt failed", () => {
  const tokenizers = new AnimaTokenizers(qwenAssets, t5Assets);
  assertEquals(tokenizers.maxLength, fixture.maxLength);
  const tags = caseById("tags");
  const ids = tokenizers.encode(tags.text);
  assertEquals([...ids.qwenIds], tags.qwenIds);
  assertEquals([...ids.t5Ids], tags.t5Ids);
  assertThrows(() => tokenizers.encode("", "negative prompt"), ModelInputError, "negative prompt");
});

test("AnimaTokenizers: an unpaired surrogate is rejected before it reaches either tokenizer", () => {
  // It passes as the text of a generation request, so it is input-caused (ADR 0107 decision 2 —
  // fixing the character makes it pass). The source of truth for the acceptance condition stays the
  // one `toCodePoints`, so the owner's diagnostic remains in `cause`.
  const tokenizers = new AnimaTokenizers(qwenAssets, t5Assets);
  const error = assertThrows(
    () => tokenizers.encode("a\ud800b", "negative prompt"),
    ModelInputError,
    "negative prompt",
  );
  assert(error.cause instanceof Error);
  assert(!(error.cause instanceof ModelInputError), "cause is the shared helper's plain Error");
  // The other side: the counterpart showing the check does not reject everything (the side that
  // lets a paired surrogate through is checked directly against the owner by
  // `anima_sampler_test.ts` — this fixture's Qwen2 vocabulary is a reduced version of the real
  // distribution and has no non-BMP byte tokens).
  assert(tokenizers.encode(caseById("tags").text).qwenIds.length >= PROMPT_MIN_TOKENS);
});

test("createTokenizers: builds from bytes (the manifest's tokenizer / tokenizer_2)", () => {
  // The JSON shape of the real assets is "a line-separated vocabulary + a count", so the entry's
  // contract includes **rejecting a count mismatch** (with missing merges BPE does not fail; only
  // the id sequence quietly becomes something else).
  const encode = (value: unknown): Uint8Array<ArrayBuffer> =>
    new TextEncoder().encode(JSON.stringify(value));
  const qwen2Json = {
    vocabText: "a\nb\nab",
    vocabCount: 3,
    mergesText: "a b",
    mergesCount: 1,
    addedTokens: [],
    classes: { letter: [[0x61, 0x7a]], number: [], space: [[0x20, 0x20]] },
    caseFold: [],
    nfcSegments: [],
    maxLength: 8,
  };
  const t5Json = {
    vocabText: "<pad>\n</s>\n<unk>\n▁\na\nb",
    scores: [0, 0, 0, -1, -1, -2],
    unkId: 2,
    eosId: 1,
    addedTokens: [],
    space: [[0x20, 0x20]],
    normalizer: { single: [], multi: [], extend: [], breakAfter: [], prepend: [] },
    maxLength: 8,
  };
  const tokenizers = createTokenizers(encode(qwen2Json), encode(t5Json));
  assertEquals(tokenizers.maxLength, 8);
  // The `a b` merge applies at rank 0, so `aba` splits into `ab` + `a` (vocab is a=0 / b=1 / ab=2).
  // It is made **two or more tokens** to lie inside the accepted set Dim(min=2).
  assertEquals([...tokenizers.encode("aba").qwenIds], [2, 0], "merged into ab by the merges");

  assertThrows(
    () => createTokenizers(encode({ ...qwen2Json, mergesCount: 2 }), encode(t5Json)),
    Error,
    "line count",
  );
  assertThrows(
    () => createTokenizers(new TextEncoder().encode("{"), encode(t5Json)),
    Error,
    "cannot be read as JSON",
  );

  // ids are copied into an `Int32Array`, so a non-integer is truncated and an out-of-range value
  // wraps, turning into "another token". Passing them only because they are numbers would not
  // surface until the embedding gather.
  assertThrows(
    () => createTokenizers(encode(qwen2Json), encode({ ...t5Json, unkId: 1.5 })),
    Error,
    "tokenizer_2.unkId: token id is not an integer in 0..2147483647 (1.5)",
  );
  assertThrows(
    () => createTokenizers(encode(qwen2Json), encode({ ...t5Json, eosId: -1 })),
    Error,
    "tokenizer_2.eosId: token id is not an integer in 0..2147483647 (-1)",
  );
  assertThrows(
    () => createTokenizers(encode(qwen2Json), encode({ ...t5Json, eosId: 6 })),
    Error,
    "tokenizer_2.eosId: token id 6 is not below the vocabulary row count 6",
  );
  // The id of an added token may point **outside** the vocabulary table (Qwen2's real assets do),
  // so no upper bound is pinned — only integrality and the i32 range are checked.
  assertThrows(
    () =>
      createTokenizers(encode({ ...qwen2Json, addedTokens: [["<|x|>", 2 ** 31]] }), encode(t5Json)),
    Error,
    "token id is not an integer in 0..2147483647 (2147483648)",
  );
  assertEquals(
    createTokenizers(encode({ ...qwen2Json, addedTokens: [["<|x|>", 3]] }), encode(t5Json))
      .maxLength,
    8,
    "an added token whose id equals the vocabulary's row count (3) passes",
  );
});

test("createTokenizers: the T5 side's added tokens must be vocabulary rows (below the row count, and the row of the same spelling)", () => {
  // Unlike Qwen2 above, every added token of the T5 family is a row of its vocabulary table, and
  // encode pushes the mapped id into the graph input as is — an id past the table surfaces only as
  // the OOB of the embedding gather, and a mismatched row silently encodes another token.
  const encode = (value: unknown): Uint8Array<ArrayBuffer> =>
    new TextEncoder().encode(JSON.stringify(value));
  const qwen2Json = {
    vocabText: "a\nb\nab",
    vocabCount: 3,
    mergesText: "a b",
    mergesCount: 1,
    addedTokens: [],
    classes: { letter: [[0x61, 0x7a]], number: [], space: [[0x20, 0x20]] },
    caseFold: [],
    nfcSegments: [],
    maxLength: 8,
  };
  const t5Json = (addedTokens: readonly [string, number][]) => ({
    vocabText: "<pad>\n</s>\n<unk>\n▁\na\nb",
    scores: [0, 0, 0, -1, -1, -2],
    unkId: 2,
    eosId: 1,
    addedTokens,
    space: [[0x20, 0x20]],
    normalizer: { single: [], multi: [], extend: [], breakAfter: [], prepend: [] },
    maxLength: 8,
  });
  assertThrows(
    () => createTokenizers(encode(qwen2Json), encode(t5Json([["<x>", 6]]))),
    Error,
    'tokenizer_2.addedTokens: "<x>" has id 6, which is >= the vocabulary row count 6',
  );
  assertThrows(
    () => createTokenizers(encode(qwen2Json), encode(t5Json([["</s>", 2]]))),
    Error,
    'tokenizer_2.addedTokens: "</s>" has id 2, which disagrees with vocabulary row 1',
  );
  // Control: a matching row, and a spelling the vocabulary does not hold, below the row count.
  assertEquals(
    createTokenizers(
      encode(qwen2Json),
      encode(
        t5Json([
          ["</s>", 1],
          ["<x>", 5],
        ]),
      ),
    ).maxLength,
    8,
  );
});

// ---- Range checks of the assets (external boundary) ---------------------------------------------
//
// `fromPretrained(ref)` can point at any repo, so the asset JSON is untrusted external input. What
// is pinned here is only the shape where "a broken table raises no exception and quietly turns into
// a different id sequence".

/**
 * The minimal assets that exercise the range checks (one valid shape written once; each test breaks
 * a single point).
 */
const gateQwen2Json = {
  vocabText: "a\nb\nab",
  vocabCount: 3,
  mergesText: "a b",
  mergesCount: 1,
  addedTokens: [],
  classes: { letter: [[0x61, 0x7a]], number: [], space: [[0x20, 0x20]] },
  caseFold: [],
  nfcSegments: [],
  maxLength: 8,
};

const gateT5Json = {
  vocabText: "<pad>\n</s>\n<unk>\n▁\na\nb",
  scores: [0, 0, 0, -1, -1, -2],
  unkId: 2,
  eosId: 1,
  addedTokens: [],
  space: [[0x20, 0x20]],
  normalizer: { single: [], multi: [], extend: [], breakAfter: [], prepend: [] },
  maxLength: 8,
};

const gateEncode = (value: unknown): Uint8Array<ArrayBuffer> =>
  new TextEncoder().encode(JSON.stringify(value));

/**
 * A pair of assets with only one side broken (the other side is always valid — the failing side can
 * be identified).
 */
const brokenQwen2 = (
  patch: Record<string, unknown>,
): [Uint8Array<ArrayBuffer>, Uint8Array<ArrayBuffer>] => [
  gateEncode({ ...gateQwen2Json, ...patch }),
  gateEncode(gateT5Json),
];
const brokenT5 = (
  patch: Record<string, unknown>,
): [Uint8Array<ArrayBuffer>, Uint8Array<ArrayBuffer>] => [
  gateEncode(gateQwen2Json),
  gateEncode({ ...gateT5Json, ...patch }),
];

test("asset range checks: maxLength is a positive safe integer (a broken asset does not turn into another diagnostic)", () => {
  // maxLength: 0 empties Qwen2's id sequence, so the diagnostic that arrives would be "the prompt
  // is empty" = **a lie** (what is broken is the asset). It fails at parse time naming maxLength.
  assertThrows(
    () => createTokenizers(...brokenQwen2({ maxLength: 0 })),
    Error,
    "tokenizer.maxLength: not a positive safe integer (0)",
  );
  // A non-integer is truncated by `slice`, so only for long prompts the id sequence length is off
  // by one.
  assertThrows(
    () => createTokenizers(...brokenQwen2({ maxLength: 1.5 })),
    Error,
    "tokenizer.maxLength: not a positive safe integer (1.5)",
  );
  assertThrows(
    () => createTokenizers(...brokenT5({ maxLength: -1 })),
    Error,
    "tokenizer_2.maxLength: not a positive safe integer (-1)",
  );
  // Above 2^53 the truncation never takes effect (the comparison loses precision).
  assertThrows(
    () => createTokenizers(...brokenQwen2({ maxLength: Number.MAX_VALUE })),
    Error,
    "tokenizer.maxLength: not a positive safe integer",
  );
});

test("asset range checks: T5's scores are finite (a polluted minScore collapses Viterbi)", () => {
  // NaN / ±Infinity pollute minScore and collapse the unknown-node weights to "every path equal".
  for (const bad of [Number.NaN, Number.POSITIVE_INFINITY, Number.NEGATIVE_INFINITY]) {
    assertThrows(
      () => createTokenizers(...brokenT5({ scores: [0, 0, 0, -1, bad, -2] })),
      Error,
      "tokenizer_2.scores[4]: not a finite number",
    );
  }
});

test("asset range checks: a table where row number = id rejects duplicate rows (the last one wins and another row is looked up)", () => {
  // Comparing row counts (vocabCount / the number of scores) cannot catch duplicates — a duplicate
  // does not change the row count.
  assertThrows(
    () => createTokenizers(...brokenQwen2({ vocabText: "a\nb\na", vocabCount: 3 })),
    Error,
    "tokenizer.vocabText: line 2 has the same token as line 0",
  );
  // For merges the rank is the BPE priority itself. A duplicate quietly changes only the splitting
  // rules.
  assertThrows(
    () => createTokenizers(...brokenQwen2({ mergesText: "a b\na b", mergesCount: 2 })),
    Error,
    "tokenizer.mergesText: line 1 has the same token as line 0",
  );
  assertThrows(
    () =>
      createTokenizers(
        ...brokenT5({ vocabText: "<pad>\n</s>\n<unk>\n▁\na\na", scores: [0, 0, 0, -1, -1, -2] }),
      ),
    Error,
    "tokenizer_2.vocabText: line 5 has the same token as line 4",
  );
});

test("asset range checks: rejects duplicate keys in keyed maps (addedTokens / caseFold)", () => {
  assertThrows(
    () =>
      createTokenizers(
        ...brokenQwen2({
          addedTokens: [
            ["<|x|>", 3],
            ["<|x|>", 4],
          ],
        }),
      ),
    Error,
    'duplicate key "<|x|>"',
  );
  assertThrows(
    () =>
      createTokenizers(
        ...brokenQwen2({
          caseFold: [
            [0x41, 0x61],
            [0x41, 0x62],
          ],
        }),
      ),
    Error,
    "tokenizer.caseFold: duplicate key 65",
  );
  assertThrows(
    () =>
      createTokenizers(
        ...brokenT5({
          addedTokens: [
            ["<x>", 3],
            ["<x>", 4],
          ],
        }),
      ),
    Error,
    "tokenizer_2.addedTokens: duplicate key ",
  );
  // caseFold's keys are code points too (aligned with the same discipline as the tables).
  assertThrows(
    () => createTokenizers(...brokenQwen2({ caseFold: [[0x110000, 0x61]] })),
    Error,
    "tokenizer.caseFold: code point is not an integer in 0..1114111",
  );
});

test("range tables: non-integers and values outside the code-point range are not accepted (the same discipline as sbv2's parseRanges)", () => {
  // `[65.5, 90]` raises no exception in the binary search and only shifts the boundary by a
  // fraction → the character classes change, the pre-token boundaries change → the id sequence
  // silently becomes something else.
  assertThrows(() => parseCodeRanges([[65.5, 90]], "table"), Error, "code point");
  assertThrows(() => parseCodeRanges([[-1, 90]], "table"), Error, "code point");
  assertThrows(() => parseCodeRanges([[65, 0x110000]], "table"), Error, "code point");
  // The exact endpoints (0 and 0x10FFFF) are inside the accepted set.
  assertEquals(parseCodeRanges([[0, 0x10ffff]], "table"), [[0, 0x10ffff]]);
});

test("normalisation tables: rejects duplicate keys, out-of-range code points and wrong tuple lengths", () => {
  const tables = (patch: Record<string, unknown>): unknown => ({
    single: [],
    multi: [],
    extend: [],
    breakAfter: [],
    prepend: [],
    ...patch,
  });
  // Letting the last one win would quietly change only the normalisation result (the tokenize id
  // sequence becomes something else).
  assertThrows(
    () =>
      parseSpmTables(
        tables({
          single: [
            [0x41, "a"],
            [0x41, "b"],
          ],
        }),
        "table",
      ),
    Error,
    "table.single: duplicate key 65",
  );
  assertThrows(
    () =>
      parseSpmTables(
        tables({
          multi: [
            [0x41, 0x42, "x"],
            [0x41, 0x42, "y"],
          ],
        }),
        "table",
      ),
    Error,
    "table.multi: duplicate key ",
  );
  // The uniqueness of the composite key `cp * 0x110000 + cp` assumes "keys are at most 0x10FFFF".
  assertThrows(
    () => parseSpmTables(tables({ single: [[0x110000, "a"]] }), "table"),
    Error,
    "table.single: code point",
  );
  assertThrows(
    () => parseSpmTables(tables({ multi: [[0x41, -1, "x"]] }), "table"),
    Error,
    "table.multi: code point",
  );
  // The tuple length is fixed as in the schema (extra elements would stay unread and hide the
  // asset's corruption).
  assertThrows(
    () => parseSpmTables(tables({ single: [[0x41, "a", "b"]] }), "table"),
    Error,
    "table.single: not [cp, string]",
  );
  assertThrows(
    () => parseSpmTables(tables({ multi: [[0x41, 0x42, "x", "y"]] }), "table"),
    Error,
    "table.multi: not [cp, cp, string]",
  );
});

/**
 * A minimal Qwen2 asset that checks only the BPE rules (the character classes and the like are
 * borrowed from the real fixture).
 */
const tinyQwen = (
  vocab: Record<string, number>,
  merges: readonly (readonly [string, string, number])[],
): Qwen2Tokenizer =>
  new Qwen2Tokenizer({
    ...qwenAssets,
    vocab: new Map(Object.entries(vocab)),
    merges: new Map(merges.map(([left, right, rank]) => [`${left} ${right}`, rank])),
    addedTokens: new Map(),
  });

test("Qwen2 BPE: the pair with the smaller rank merges first, and at equal rank the left pair merges first", () => {
  const vocab = { a: 0, aa: 1, b: 2, c: 3, bc: 4, ab: 5 };
  // At equal rank (the same pair in a row) from the left: aaa → aa + a (not a + aa).
  assertEquals(tinyQwen(vocab, [["a", "a", 0]]).encode("aaa"), [1, 0]);
  // Rank takes precedence over position: b c (rank 0) merges before a b (rank 1).
  assertEquals(
    tinyQwen(vocab, [
      ["b", "c", 0],
      ["a", "b", 1],
    ]).encode("abc"),
    [0, 4],
  );
  assertEquals(
    tinyQwen(vocab, [
      ["b", "c", 1],
      ["a", "b", 0],
    ]).encode("abc"),
    [5, 3],
  );
});

test("Qwen2 BPE: merging does not become quadratic even on a long single piece without separators", () => {
  // The truncation (512) only acts per piece, so the BPE of one piece runs to the end. A run of
  // Latin letters without separators, or Japanese without punctuation, is a single piece by
  // character class. A form that repeats a scan of every adjacent pair plus a splice at each merge
  // takes over a second at 8,000 characters.
  const qwen2 = tinyQwen({ a: 0, aa: 1 }, [["a", "a", 0]]);
  const started = performance.now();
  const ids = qwen2.encode("a".repeat(8_000));
  const elapsed = performance.now() - started;
  assertEquals(
    ids,
    Array.from({ length: 512 }, () => 1),
  );
  assert(elapsed < 300, `BPE of one piece of 8,000 characters took ${elapsed.toFixed(0)} ms`);
});
